import { expect, test } from "bun:test";
import { needsReorder } from "../src/inventory";
test("equality keeps current inventory", () => expect(needsReorder(12, 12)).toBe(false));
test("a shortage triggers reorder", () => expect(needsReorder(11, 12)).toBe(true));
test("excess stock does not reorder", () => expect(needsReorder(13, 12)).toBe(false));

